#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    int countCharacters(vector<string>& words, string chars) {
        vector<int> freq(26, 0);
        for (char c : chars) freq[c - 'a']++;

        int total = 0;
        for (string& word : words) {
            vector<int> temp = freq;
            bool valid = true;
            for (char c : word) {
                if (--temp[c - 'a'] < 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) total += word.length();
        }

        return total;
    }
};
